// components/ChatScreen.tsx
import { useEffect } from 'react';
import { useChatStore } from '../stores/chatStore';
import { websocketService } from '../services/websocket.service';

export const ChatScreen = ({ route }) => {
  const { chatId } = route.params;
  const { addMessage, setTypingStatus } = useChatStore();

  useEffect(() => {
    // Écouter les nouveaux messages
    const onNewMessage = (data) => {
      if (data.chatId === chatId) {
        addMessage(data.message);
      }
    };

    // Écouter les statuts de frappe
    const onTyping = (data) => {
      if (data.chatId === chatId) {
        setTypingStatus(data.userId, data.isTyping);
      }
    };

    websocketService.on('new_message', onNewMessage);
    websocketService.on('typing_status', onTyping);

    // Rejoindre la room du chat
    websocketService.emit('join_room', { roomId: chatId });

    // Nettoyage
    return () => {
      websocketService.off('new_message', onNewMessage);
      websocketService.off('typing_status', onTyping);
      websocketService.emit('leave_room', { roomId: chatId });
    };
  }, [chatId]);

  // ... reste du composant
};
