// stores/connectionStatusStore.ts
import { create } from 'zustand';

export type ConnectionStatus = 'connected' | 'connecting' | 'disconnected' | 'reconnecting';

interface ConnectionStatusState {
  status: ConnectionStatus;
  reconnectAttempts: number;
  maxAttempts: number;
  setStatus: (status: ConnectionStatus) => void;
  incrementAttempts: () => void;
  resetAttempts: () => void;
  getBackoffDelay: () => number;
}

export const useConnectionStatusStore = create<ConnectionStatusState>((set, get) => ({
  status: 'disconnected',
  reconnectAttempts: 0,
  maxAttempts: 5,

  setStatus: (status) => set({ status }),

  incrementAttempts: () => {
    const { reconnectAttempts } = get();
    set({ reconnectAttempts: reconnectAttempts + 1 });
  },

  resetAttempts: () => set({ reconnectAttempts: 0 }),

  getBackoffDelay: () => {
    const { reconnectAttempts } = get();
    const baseDelay = 1000; // 1 seconde
    return Math.min(baseDelay * Math.pow(2, reconnectAttempts), 30000); // max 30s
  },
}));
